<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Modal, message } from 'ant-design-vue'
import { getPerson } from '@/services/iamPeople'
import { listDepartments } from '@/services/iamDepartments'
import { getEffectiveWork, getWorkSubject, previewWork, saveWork, workAction, savedWorkResult, changedWork, type WorkDraft } from '@/services/iamWork'
import { canIam, iamMessage } from '@/services/iamAccess'
import type { WorkApp, WorkChange, WorkPreview, WorkTarget, WorkScope } from '@/types/iam'
import AttendanceAccessSummary from './AttendanceAccessSummary.vue'
const props = defineProps<{ subjectKind: 'employee' | 'department'; subjectId: string; appId: string }>()
const emit = defineEmits<{ back: []; saved: [] }>()
const app = ref<WorkApp | null>(null), target = ref<WorkTarget | null>(null), loading = ref(true), busy = ref(false), error = ref(''), editing = ref(false), canConfigure = ref(false)
const original = ref<WorkChange[]>([]), draft = ref<WorkChange[]>([]), preview = ref<WorkPreview | null>(null), action = ref<'save' | 'restore' | 'suspend' | 'reenable'>('save')
let generation = 0
const changes = computed(() => changedWork(original.value, draft.value)), dirty = computed(() => editing.value && changes.value.length > 0)
const ordinary = computed(() => app.value?.operations.filter(row => !row.important) || []), important = computed(() => app.value?.operations.filter(row => row.important) || [])
const canManageApp = computed(() => canConfigure.value && canIam(props.subjectKind === 'department' ? 'iam.departments.manage' : 'iam.access.manage') && app.value?.integrated)
const canEditWork = computed(() => canManageApp.value && ordinary.value.some(row => row.editable))
const scopeKey = (scope: WorkScope) => JSON.stringify([scope.scope_type, scope.scope_ref])
function setDraft() { original.value = (app.value?.operations.filter(row => row.editable && !row.important) || []).map(row => ({ operation_id: row.operation_id, enabled: row.enabled, scopes: row.scopes.map(({scope_type,scope_ref}) => ({scope_type,scope_ref})) })); draft.value = JSON.parse(JSON.stringify(original.value)); preview.value = null }
async function load(preserve = false) { const run = ++generation; loading.value = true; error.value = ''; try { let subjectName = props.subjectId; if (props.subjectKind === 'employee') { const person = canIam('iam.people.read') ? await getPerson(props.subjectId) : await getWorkSubject(props.subjectId,props.appId); subjectName = person.employee.user_id || ''; canConfigure.value = Boolean(subjectName) && person.employee.account_status === 'active'; if (!subjectName) throw new Error('尚未开通员工账号，请先完成开户或关联。部门默认安排可在应用清单查看。') } else { const departments = await listDepartments(); canConfigure.value = departments.items.some(row => row.id === props.subjectId && row.confirmed === true) }; const next = { subject_type: props.subjectKind === 'employee' ? 'User' as const : 'Department' as const, subject_name: subjectName, app_id: props.appId }; const saved = await getEffectiveWork(next); if (run !== generation) return; target.value = next; app.value = saved; if (!preserve) { setDraft(); editing.value = false } else original.value = saved.operations.filter(row => row.editable && !row.important).map(row => ({ operation_id: row.operation_id, enabled: row.enabled, scopes: row.scopes.map(({scope_type,scope_ref}) => ({scope_type,scope_ref})) })); preview.value = null } catch (e) { if (run === generation) error.value = iamMessage(e) } finally { if (run === generation) loading.value = false } }
function workDraft(): WorkDraft { if (!app.value || !target.value) throw new Error('请先读取已保存设置。'); return { target: target.value, changes: changes.value, expected_version: app.value.version, context_revision: app.value.context_revision } }
async function prepare(kind: typeof action.value = 'save') { if (busy.value || !canManageApp.value || (kind === 'save' && !canEditWork.value)) return; error.value = ''; if (kind === 'save' && !changes.value.length) return; if (kind === 'save' && changes.value.some(row => row.enabled && !row.scopes.length)) { error.value = '请为每项已勾选工作选择明确对象范围。'; return }; busy.value = true; try { action.value = kind; preview.value = await previewWork({ ...workDraft(), changes: kind === 'save' ? changes.value : [] }, kind === 'save' ? undefined : kind); if (!preview.value.changed) { preview.value = null; message.info('当前设置无需变更。') } } catch (e) { error.value = iamMessage(e) } finally { busy.value = false } }
async function commit() { if (!preview.value || !canManageApp.value || (action.value === 'save' && !canEditWork.value) || busy.value) return; busy.value = true; error.value = ''; try { const current = preview.value; const result = action.value === 'save' ? await saveWork(workDraft(), current, crypto.randomUUID()) : await workAction(({restore:'restore_department_work',suspend:'suspend_app',reenable:'reenable_app'} as const)[action.value], target.value!, current.version, current.context_revision, crypto.randomUUID()); app.value = savedWorkResult(result,app.value!,target.value!); editing.value=false; setDraft(); message.success('工作安排已保存。'); emit('saved') } catch (e) { error.value = iamMessage(e); preview.value = null } finally { busy.value = false } }
function impactResult(row: {result?:string;before?:string;after?:string}) { return row.result || [row.before,row.after].filter(text => typeof text === 'string' && text).join(' → ') || '已按当前安排核对' }
function changeScopes(row: WorkChange, keys: unknown[]) { row.scopes = keys.map(key => { const [scope_type, scope_ref] = JSON.parse(String(key)); return {scope_type,scope_ref} }); preview.value = null }
async function requestLeave() { if (busy.value) return false; if (!dirty.value) return true; return new Promise<boolean>(resolve => Modal.confirm({ title: '放弃尚未保存的工作草稿？', content: '已保存的安排不受影响。', okText: '放弃草稿', cancelText: '继续编辑', onOk: () => resolve(true), onCancel: () => resolve(false) })) }
async function back() { if (await requestLeave()) emit('back') }
watch(() => [props.subjectKind,props.subjectId,props.appId], () => load(), { immediate: true }); defineExpose({ requestLeave })
</script>
<template><section class="work-settings"><div class="work-head"><a-button :disabled="busy" @click="back">返回应用清单</a-button><h2>{{ app?.title || '应用工作安排' }}</h2></div><a-alert v-if="error" :message="error" type="warning" show-icon /><a-button v-if="error" :disabled="busy" @click="load(editing)">读取最新设置，保留草稿</a-button><a-skeleton v-if="loading" active /><template v-else-if="app"><p class="business-summary">{{ app.summary }}</p><a-alert v-if="!app.integrated" message="尚未接入此管理功能，暂不能在此调整。" type="info" /><a-alert v-if="!canConfigure" message="目标状态尚未确认，当前只读。" type="info" />
  <template v-if="!editing"><article v-for="row in ordinary" :key="row.operation_id" class="work-row"><strong>{{ row.label }}</strong><span>{{ row.reason || (row.enabled ? `范围：${row.scopes.map(scope => scope.label || (scope.scope_type === 'SELF' ? '本人' : scope.scope_ref)).join('、')}` : '未安排') }}</span><small>{{ row.source_text }}</small></article><AttendanceAccessSummary v-if="app.app_id === 'attendance' && subjectKind === 'employee'" :app="app" /><a-button v-if="canEditWork" type="primary" @click="editing = true; setDraft()">修改工作与对象</a-button></template>
  <template v-else><p class="aux">只保存你本次修改的工作。未修改项目的部门来源保持不变。</p><section v-for="row in draft" :key="row.operation_id" class="work-row"><a-checkbox v-model:checked="row.enabled" :disabled="busy || Boolean(preview)" @change="row.scopes = row.enabled ? row.scopes : []; preview = null">{{ ordinary.find(item => item.operation_id === row.operation_id)?.label }}</a-checkbox><template v-if="row.enabled"><label>可使用的对象</label><a-checkbox-group :disabled="busy || Boolean(preview)" :value="row.scopes.map(scopeKey)" @change="(values: unknown[]) => changeScopes(row, values)"><a-checkbox v-for="scope in ordinary.find(item => item.operation_id === row.operation_id)?.objects || []" :key="scopeKey(scope)" :value="scopeKey(scope)">{{ scope.label || (scope.scope_type === 'SELF' ? '本人' : scope.scope_ref) }}</a-checkbox></a-checkbox-group></template></section><div class="work-footer"><a-button :disabled="busy" @click="editing = false; setDraft()">取消修改</a-button><a-button type="primary" :disabled="!dirty" :loading="busy" @click="prepare()">预览并保存</a-button></div></template>
  <details v-if="important.length"><summary>重要权限（仅查看）</summary><p class="aux">重要权限不会随普通部门安排获得，也不能在此授予。</p><article v-for="row in important" :key="row.operation_id" class="work-row"><strong>{{ row.label }}</strong><span>{{ row.reason || (row.enabled ? '请通过专门流程核验资格与用途' : '未授予') }}</span><small>{{ row.source_text }}</small></article></details>
  <details v-if="subjectKind === 'employee' && canManageApp && !editing"><summary>其他安排</summary><div class="secondary-actions"><a-button @click="prepare('restore')">恢复部门普通安排</a-button><a-button v-if="!app.suspended" danger @click="prepare('suspend')">只停用此人此应用</a-button><a-button v-else @click="prepare('reenable')">重新启用并核对当前安排</a-button></div></details>
  <section v-if="preview" class="preview" aria-live="polite"><h3>确认本次变更</h3><p>{{ preview.summary }}</p><template v-if="subjectKind === 'department' && preview.impact"><p>跟随变化 {{ preview.impact.changed }} 人；个人安排保留 {{ preview.impact.personal_preserved }} 人；不可用 {{ preview.impact.unavailable }} 人。</p><details><summary>查看全部受影响员工</summary><p v-for="(row,index) in preview.impact.employees" :key="index">{{ row.name }}：{{ impactResult(row) }}{{ row.personal_preserved ? '（保留个人安排）' : '' }}</p></details></template><p class="aux">提交时服务端会重新检查当前管理范围、来源、期限和资格。</p><a-button :disabled="busy" @click="preview = null">返回核对</a-button><a-button type="primary" :loading="busy" @click="commit">确认保存一次</a-button></section>
</template></section></template>
<style scoped>.work-settings{display:grid;gap:var(--hbos-space-4);min-width:0;font-size:16px}.work-head{display:flex;gap:var(--hbos-space-3);align-items:center;flex-wrap:wrap}.work-head h2{font-size:20px;margin:0}.business-summary{font-size:18px;line-height:1.6;margin:0}.work-row{display:grid;gap:8px;padding:var(--hbos-space-4);border:1px solid var(--hbos-border-subtle,#dce5e0);border-radius:var(--hbos-radius-md)}.work-row small,.aux{font-size:14px;color:var(--hbos-text-secondary);line-height:1.6}.work-footer{position:sticky;bottom:0;display:flex;justify-content:flex-end;gap:12px;background:var(--hbos-surface-solid,#fff);padding:16px 0}.secondary-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}.preview{padding:20px;border:1px solid #8eaf9c;border-radius:12px;background:#f2f8f4}.preview .ant-btn+.ant-btn{margin-left:12px}summary{cursor:pointer;font-size:14px;font-weight:600}</style>
